checks.command:
@'
import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { buildSkillPackage } from './packages/core/src/domain/skill-package.ts';
import { validatePackage } from './packages/core/src/application/validate-package.ts';

const root = resolve('skills/hot-partitions-and-rebalancing');
const paths = ['SKILL.md', 'skill.yaml', 'references/detecting-skew.md', 'references/repairs-and-rebalancing.md'];
const parsed = parseManifest(readFileSync(resolve(root, 'skill.yaml'), 'utf8'), { strict: true });
const pkg = buildSkillPackage(parsed.manifest, paths.map(path => ({ path, bytes: readFileSync(resolve(root, path)) })));
const report = validatePackage(pkg, { directoryName: 'hot-partitions-and-rebalancing' });
const failures = [...parsed.issues, ...report.issues];
const resources = [];
for (const path of paths.filter(path => path.endsWith('.md'))) {
  const source = readFileSync(resolve(root, path), 'utf8');
  for (const match of source.matchAll(/\]\(([^)]+)\)/g)) {
    const target = match[1].replace(/^<|>$/g, '');
    if (/^https?:/.test(target)) continue;
    const filePart = target.split('#')[0];
    const absolute = resolve(dirname(resolve(root, path)), filePart || path.split('/').at(-1));
    resources.push({ from: path, target, exists: existsSync(absolute) });
    if (!existsSync(absolute)) failures.push({ missing: target, from: path });
  }
  for (const match of source.matchAll(/\x60((?:references|assets|scripts)\/[^\x60]+)\x60/g)) {
    const absolute = resolve(root, match[1].split('#')[0]);
    resources.push({ from: path, target: match[1], exists: existsSync(absolute) });
    if (!existsSync(absolute)) failures.push({ missing: match[1], from: path });
  }
}
const related = [...parsed.manifest.dependencies.map(item => item.name), ...parsed.manifest.suggests];
const missingRelated = related.filter(name => !existsSync(resolve('skills', name, 'SKILL.md')));
if (missingRelated.length) failures.push({ missingRelated });
console.log(JSON.stringify({ skill: parsed.manifest.name, version: parsed.manifest.version, files: paths.length, packageReport: report, parseIssues: parsed.issues, resources, relatedSkillsChecked: related.length, missingRelated, failures }, null, 2));
process.exitCode = failures.length ? 1 : 0;
'@ | node --input-type=module

